import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'
import type { Goal, Run, Task } from '../types'

const suggestions = atom({ plugin: 'next-prompts', key: 'suggestions' } as const, [] as string[])
const isThinking = atom({ plugin: 'next-prompts', key: 'isThinking' } as const, false)
const tasks = atom({ plugin: 'next-prompts', key: 'tasks' } as const, [] as Task[])
const goal = atom({ plugin: 'next-prompts', key: 'goal' } as const, null as Goal | null)
const run = atom({ plugin: 'next-prompts', key: 'run' } as const, null as Run | null)
const tick = atom({ plugin: 'next-prompts', key: 'tick' } as const, 0)
const showAll = atom({ plugin: 'next-prompts', key: 'showAll' } as const, false)

const CYAN = '#00B8D4'
const NEON_CYAN = '#00FFFF'
const SHOWN_TASKS = 5
const IDLE_TICK_EVERY = 15 // seconds between redraws when Claude is idle

// Suggestions: Haiku reads only the last few exchanges, trimmed, so it stays fast.
const LOOKBACK = 3
const MAX_CHARS = 1500
const SUGGEST_TIMEOUT_MS = 15000
const MAX_GIT_LINES = 30
const ASK = `Suggest exactly 3 prompts the user should send next to push the project forward most effectively. Use the project state (goal, open tasks, uncommitted changes) as well as the conversation. If tasks are unfinished, make suggestion 1 continue the next unfinished task. Make each one concrete and self-contained (one sentence, under 200 characters), ordered by impact. Reply with exactly 3 lines formatted "1. ...", "2. ...", "3. ..." and nothing else.`

// Alert when a request ran this long, so the user can step away.
const LONG_TURN_MS = 2 * 60 * 1000
const DONE_SOUND = '/System/Library/Sounds/Glass.aiff'

// Estimate: Claude must report one before it changes anything.
const ESTIMATE_TOOL = 'mcp__next-prompts__estimate'
const CHANGE_TOOLS = /^(Edit|Write|NotebookEdit|Bash)$/
const ESTIMATE_RULE = `Before making any changes for a request (before any Edit, Write, NotebookEdit or Bash call), call the ${ESTIMATE_TOOL} tool once with your best estimate of how many seconds the whole request will take you, and a few words on the plan. If the scope changes a lot mid-way, call it again with a revised estimate. Skip it for pure questions that need no changes.`

type Msg = { role: 'user' | 'assistant'; text: string; toolUses: readonly { tool: string }[]; toolResults?: readonly unknown[] }
type Status = Task['status']

// "1m 12s", or "9s" under a minute.
export function fmtClock(ms: number): string {
  const total = Math.max(0, Math.round(ms / 1000))
  const m = Math.floor(total / 60)
  return m ? `${m}m ${String(total % 60).padStart(2, '0')}s` : `${total}s`
}

const fmtTime = (ms: number) => new Date(ms).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' })

export function bar(done: number, total: number, width: number): [string, string] {
  const filled = total > 0 ? Math.min(width, Math.round((done / total) * width)) : 0
  return ['█'.repeat(filled), '░'.repeat(width - filled)]
}

export function parseSuggestions(text: string): string[] {
  return text
    .split('\n')
    .map(line => line.trim().match(/^[1-3][.)]\s+(.+)$/)?.[1]?.trim())
    .filter((s): s is string => !!s)
    .slice(0, 3)
}

// The last LOOKBACK typed prompts and everything after them, trimmed.
export function recentExchange(messages: readonly Msg[]): string {
  const starts = messages.flatMap((m, i) => (m.role === 'user' && !m.toolResults?.length && m.text.trim() ? [i] : []))
  return messages
    .slice(starts.at(-LOOKBACK) ?? 0)
    .filter(m => m.text.trim() || m.toolUses.length)
    .map(m => {
      const tools = m.toolUses.length ? ` [tools: ${m.toolUses.map(t => t.tool).join(', ')}]` : ''
      const text = m.text.length > MAX_CHARS ? `${m.text.slice(0, MAX_CHARS)} ...` : m.text
      return `${m.role.toUpperCase()}: ${text}${tools}`
    })
    .join('\n\n')
}

// What Haiku should know about the project beyond the chat.
export function projectState(goalText: string | undefined, list: readonly Task[], git: string): string {
  const open = list.filter(t => t.status !== 'completed')
  const lines = [
    goalText ? `Goal: ${goalText}` : '',
    list.length ? `Tasks: ${list.length - open.length} of ${list.length} done` : '',
    ...open.map(t => `- ${t.status === 'in_progress' ? '[in progress]' : '[todo]'} ${t.subject}`),
    git.trim() ? `git status:\n${git.trim().split('\n').slice(0, MAX_GIT_LINES).join('\n')}` : '',
  ]
  return lines.filter(Boolean).join('\n')
}

async function gitStatus($: EngineInterface): Promise<string> {
  try {
    const { exitCode, stdout } = await $.process.run(['git', 'status', '--short', '--branch'])
    return exitCode === 0 ? String(stdout) : ''
  } catch {
    return ''
  }
}

// Toast, sound and a macOS notification once a long request finishes.
async function alertDone($: EngineInterface, tookMs: number) {
  const msg = `Claude finished · took ${fmtClock(tookMs)}`
  $.ui.toast(msg)
  await Promise.allSettled([
    $.process.run(['afplay', DONE_SOUND]),
    $.process.run(['osascript', '-e', `display notification "${msg}" with title "Claude Code"`]),
  ])
}

// Sets a task's status, stamping when it started and finished.
function stamp(t: Task, status: Status, now: number): Task {
  return {
    ...t,
    status,
    startedAt: status === 'pending' ? t.startedAt : (t.startedAt ?? now),
    doneAt: status === 'completed' ? (t.doneAt ?? now) : undefined,
  }
}

// Merges a TodoWrite list into the current tasks, keeping their timestamps.
export function mergeTodos(prev: readonly Task[], todos: readonly { content: string; status: Status }[], now: number): Task[] {
  return todos.map((t, i) => {
    const old = prev.find(p => p.subject === t.content)
    return stamp(old ?? { id: `todo-${i}`, subject: t.content, status: 'pending' }, t.status, now)
  })
}

async function setTasks($: EngineInterface, goalText: string, fn: (prev: Task[], now: number) => Task[]) {
  const now = await $.clock.now()
  const after = await update($, tasks, prev => fn(prev, now))
  if (after.length && !(await read($, goal))) {
    await update($, goal, () => ({ text: goalText || 'Current goal', startedAt: now }))
  }
}

// Clears the suggestions; the caller cancels any still being generated.
async function clearSuggestions($: EngineInterface) {
  await update($, suggestions, () => [])
  await update($, isThinking, () => false)
}

// Stores Claude's estimate for the running request (typed loosely: the
// connected-MCP tool union is too deep for TypeScript to infer here).
async function recordEstimate($: EngineInterface, e: unknown): Promise<{ result: string }> {
  const input = e as { seconds?: number; plan?: string }
  const secs = Math.min(4 * 3600, Math.max(5, Math.round(Number(input.seconds) || 0)))
  await update($, run, r => (r ? { ...r, estimateMs: secs * 1000, plan: input.plan } : r))
  return { result: `Estimate recorded: ${secs}s. The user sees a live progress bar against it.` }
}

export const register: Register = on => {
  let inFlight = new AbortController()
  let lastPrompt = ''
  let running = false
  let nextTaskId = 1

  on('session.start', async ($, e, next) => {
    await $.tool.register({
      name: 'estimate',
      description: 'Report your best estimate of how long the current request will take, before you start making changes. Shown to the user as a live progress bar.',
      inputSchema: {
        type: 'object',
        properties: {
          seconds: { type: 'integer', minimum: 5, description: 'Estimated total seconds to finish the whole request' },
          plan: { type: 'string', description: 'A few words on what you will do' },
        },
        required: ['seconds'],
      },
    })
    // Every second while Claude works (smooth timer bar); every 15s otherwise.
    let seconds = 0
    $.clock.every(1000, () => {
      seconds += 1
      if (running || seconds % IDLE_TICK_EVERY === 0) void update($, tick, n => n + 1)
    })
    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const res = await next(e)
    return { ...res, sections: [...res.sections, { id: 'next-prompts-estimate', text: ESTIMATE_RULE, scope: 'session' as const }] }
  })

  // Typing just "1", "2" or "3" and pressing Enter sends that suggestion.
  on('prompt.submit', async ($, e, next) => {
    const choice = e.text.trim()
    const pick = /^[1-3]$/.test(choice) ? (await read($, suggestions))[Number(choice) - 1] : undefined
    lastPrompt = pick ?? choice
    const current = await read($, tasks)
    if (current.length && current.every(t => t.status === 'completed')) {
      await update($, tasks, () => [])
      await update($, goal, () => null)
    }
    inFlight.abort()
    await clearSuggestions($)
    return next(pick ? { ...e, text: pick } : e)
  })

  on('turn.start', async ($, e, next) => {
    running = true
    const startedAt = await $.clock.now()
    await update($, run, () => ({ startedAt }))
    return next(e)
  })

  on('turn.complete', async ($, e, next) => {
    running = false
    const finished = await read($, run)
    await update($, run, () => null)
    const result = await next(e)
    if (finished) {
      const took = (await $.clock.now()) - finished.startedAt
      if (took >= LONG_TURN_MS) void alertDone($, took)
    }

    inFlight.abort()
    const mine = (inFlight = new AbortController())
    void (async () => {
      await update($, isThinking, () => true)
      try {
        const [messages, git, taskList, g] = await Promise.all([$.session.messages(), gitStatus($), read($, tasks), read($, goal)])
        const project = projectState(g?.text, taskList, git)
        const reply = await $.model.complete(
          {
            model: 'haiku',
            prompt: `<project>\n${project || '(no tasks or git changes)'}\n</project>\n\n<conversation>\n${recentExchange(messages)}\n</conversation>\n\n${ASK}`,
            maxTokens: 300,
            effort: 'low',
            timeoutMs: SUGGEST_TIMEOUT_MS,
          },
          { signal: mine.signal },
        )
        if (!mine.signal.aborted) await update($, suggestions, () => (reply.isAnswered ? parseSuggestions(reply.text) : []))
      } finally {
        if (!mine.signal.aborted) await update($, isThinking, () => false)
      }
    })()
    return result
  })

  // Claude's estimate arrives through its own tool. TypeScript gives up on the
  // union of every connected MCP tool here; the handler is typed by hand above.
  // @ts-ignore TS2589
  on('tool.call', { tool: /^mcp__next-prompts__estimate$/ }, recordEstimate)

  // No changes until Claude has given its estimate for this request.
  on('tool.call', { tool: CHANGE_TOOLS }, async ($, e, next) => {
    const r = await read($, run)
    if (r && r.estimateMs === undefined && !(e as { agentId?: string }).agentId) {
      return { deny: `First call ${ESTIMATE_TOOL} with your best estimate (in seconds) of how long this whole request will take, then retry.` }
    }
    return next(e)
  })

  on('tool.call', { tool: 'TodoWrite' }, async ($, e, next) => {
    const res = await next(e)
    await setTasks($, lastPrompt, (prev, now) => mergeTodos(prev, e.todos ?? [], now))
    return res
  })

  on('tool.call', { tool: 'TaskCreate' }, async ($, e, next) => {
    const res = await next(e)
    const id = String(res.text ?? JSON.stringify(res.result ?? '')).match(/#(\d+)/)?.[1] ?? String(nextTaskId)
    nextTaskId = Number(id) + 1
    await setTasks($, lastPrompt, prev => [...prev, { id, subject: e.subject, status: 'pending' }])
    return res
  })

  on('tool.call', { tool: 'TaskUpdate' }, async ($, e, next) => {
    const res = await next(e)
    await setTasks($, lastPrompt, (prev, now) =>
      e.status === 'deleted'
        ? prev.filter(t => t.id !== e.taskId)
        : prev.map(t => (t.id === e.taskId ? stamp({ ...t, subject: e.subject ?? t.subject }, (e.status as Status) ?? t.status, now) : t)),
    )
    return res
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const [list, thinking, taskList, g, r, expanded] = await Promise.all([
      read($, suggestions),
      read($, isThinking),
      read($, tasks),
      read($, goal),
      read($, run),
      read($, showAll),
      read($, tick), // subscribes this drawing to the clock
    ])
    if (e.props.hasSurvey || (!r && !thinking && !list.length && !taskList.length)) return next(e)

    const { Box, Button, Text } = $.ui.resolve(e)
    const now = await $.clock.now()
    const cols = Math.max(10, e.props.bodyColumns)

    // ── full-width timer: elapsed vs. Claude's own estimate
    let timer = null
    if (r) {
      const elapsed = now - r.startedAt
      if (r.estimateMs === undefined) {
        timer = (
          <Text>
            <Text color={CYAN}>⏱ {fmtClock(elapsed)}</Text>
            <Text dimColor> · waiting for Claude's estimate…</Text>
          </Text>
        )
      } else {
        const estimate = r.estimateMs
        const over = elapsed > estimate
        const [filled, empty] = bar(elapsed, estimate, cols)
        timer = (
          <Box flexDirection="column">
            <Text>
              <Text color={over ? 'yellow' : CYAN}>⏱ {fmtClock(elapsed)}</Text>
              <Text dimColor>
                {over
                  ? ` · ${fmtClock(elapsed - estimate)} past Claude's ~${fmtClock(estimate)} estimate`
                  : ` of Claude's ~${fmtClock(estimate)} estimate · done ≈${fmtTime(r.startedAt + estimate)} · ${Math.round((elapsed / estimate) * 100)}%`}
                {r.plan ? ` · ${r.plan.slice(0, 60)}` : ''}
              </Text>
            </Text>
            <Text>
              <Text color={over ? 'yellow' : CYAN}>{filled}</Text>
              <Text dimColor>{empty}</Text>
            </Text>
          </Box>
        )
      }
    }

    // ── goal panel: title, task progress bar, task list
    let goalPanel = null
    if (g && taskList.length) {
      const done = taskList.filter(t => t.status === 'completed').length
      const [filled, empty] = bar(done, taskList.length, cols)
      const order = { in_progress: 0, completed: 1, pending: 2 } as const
      const sorted = [...taskList].sort((a, b) => order[a.status] - order[b.status])
      goalPanel = (
        <Box flexDirection="column">
          <Box>
            <Text bold>◎ Goal: {g.text.length > 70 ? `${g.text.slice(0, 70)}…` : g.text}  </Text>
            <Text color={CYAN}>
              {done} of {taskList.length} tasks · {Math.round((done / taskList.length) * 100)}%
            </Text>
          </Box>
          <Text>
            <Text color={CYAN}>{filled}</Text>
            <Text dimColor>{empty}</Text>
          </Text>
          <Text dimColor>
            {fmtClock(now - g.startedAt)} elapsed{done === taskList.length ? ' · done' : ''}
          </Text>
          {(expanded ? sorted : sorted.slice(0, SHOWN_TASKS)).map(t =>
            t.status === 'completed' ? (
              <Text key={t.id} dimColor>
                <Text color="green">✓</Text> {t.subject}  {t.startedAt && t.doneAt ? fmtClock(t.doneAt - t.startedAt) : ''}
              </Text>
            ) : t.status === 'in_progress' ? (
              <Text key={t.id}>
                <Text color={CYAN}>▶</Text> <Text bold>{t.subject}</Text>
                <Text dimColor>  running {fmtClock(now - (t.startedAt ?? now))}</Text>
              </Text>
            ) : (
              <Text key={t.id}>○ {t.subject}</Text>
            ),
          )}
          {sorted.length > SHOWN_TASKS && (
            <Button
              key="all"
              label={expanded ? 'fewer tasks' : `+${sorted.length - SHOWN_TASKS} more`}
              onPress={() => update($, showAll, v => !v)}
            />
          )}
        </Box>
      )
    }

    // ── next-prompt suggestions
    const send = (text: string) => async () => {
      lastPrompt = text // our own submit skips our prompt.submit hook
      inFlight.abort()
    await clearSuggestions($)
      await $.prompt.submit({ text, asUser: true })
    }
    const nextPrompts = thinking ? (
      <Text dimColor>Next prompts: thinking…</Text>
    ) : list.length ? (
      <Box flexDirection="column">
        <Text dimColor>Next prompts (click, or type 1/2/3 + Enter):</Text>
        {list.map((text, i) => (
          <Box key={String(i)}>
            <Button key={`b${i}`} label={String(i + 1)} onPress={send(text)} />
            <Text color={i === 1 ? NEON_CYAN : undefined}> {text}</Text>
          </Box>
        ))}
      </Box>
    ) : null

    return (
      <Box flexDirection="column">
        {timer}
        {goalPanel}
        {nextPrompts}
      </Box>
    )
  })
}

