export type Suggestions = string[]
export type Task = { id: string; subject: string; status: 'pending' | 'in_progress' | 'completed'; startedAt?: number; doneAt?: number }
export type Run = { startedAt: number; estimateMs?: number; plan?: string }
export type Goal = { text: string; startedAt: number }

declare module 'claude-code' {
  interface PluginState {
    'next-prompts': {
      suggestions: Suggestions
      isThinking: boolean
      tasks: Task[]
      goal: Goal | null
      run: Run | null
      tick: number
      showAll: boolean
    }
  }
}
